export function createMockDocFile(name: string, content: string = "Official Enterprise Payroll Document"): any {
  if (typeof File !== "undefined") {
    try {
      return new File([content], name, { type: "application/pdf" });
    } catch {
      // fallback
    }
  }
  return { name, size: content.length * 1024, type: "application/pdf" };
}

